import{K as r,a as l,c as i,b as t,k as d,q as n,ac as c}from"./chunks/framework.BSuaGltH.js";const f=JSON.parse('{"title":"Word 邮件合并、批量通知与标签","description":"使用 Excel 收件人名单和 Word 合并域批量生成通知，预览筛选记录，处理日期金额前导零并输出个人文档或标签。","frontmatter":{"title":"Word 邮件合并、批量通知与标签","description":"使用 Excel 收件人名单和 Word 合并域批量生成通知，预览筛选记录，处理日期金额前导零并输出个人文档或标签。","showdocs":{"topics":[{"id":"office","title":"Office","link":"/topics/office/"}],"kind":"使用指南","scope":"general","audience":"general","group":"工程与工具","seriesTitle":"Office · Word 文档排版","summary":"使用 Excel 收件人名单和 Word 合并域批量生成通知，预览筛选记录，处理日期金额前导零并输出个人文档或标签。","status":"active","related":[{"title":"Excel 实战：建立可刷新、可核对的月报","link":"/tools/office/excel/project","kind":"实践案例","scope":"general","audience":"general"},{"title":"Office 常见问题排查与交付检查表","link":"/tools/office/collaboration/troubleshooting","kind":"故障排查","scope":"general","audience":"general"},{"title":"Office 常用快捷键、选择与粘贴技巧","link":"/tools/office/start/shortcuts","kind":"参考资料","scope":"general","audience":"general"},{"title":"Office 综合实战：从数据到报告、演示和会议","link":"/tools/office/collaboration/workflow","kind":"实践案例","scope":"general","audience":"general"},{"title":"Word 实战：制作可维护的项目报告","link":"/tools/office/word/report","kind":"实践案例","scope":"general","audience":"general"}],"prev":{"text":"Word 修订、批注、比较与定稿","link":"/tools/office/word/review"},"next":{"text":"Word 实战：制作可维护的项目报告","link":"/tools/office/word/report"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"Word 修订、批注、比较与定稿","link":"/tools/office/word/review"},"next":{"text":"Word 实战：制作可维护的项目报告","link":"/tools/office/word/report"}},"headers":[],"relativePath":"tools/office/word/mail-merge.md","filePath":"tools/office/word/mail-merge.md"}'),h={name:"tools/office/word/mail-merge.md"},k=Object.assign(h,{setup(s){const a={path:"/tools/office/word/mail-merge",app:"Word",title:"批量生成三份不同姓名的通知",steps:[{tab:"邮件",command:"选择收件人",setting:"使用现有列表；来源：练习名单.xlsx",anchor:"walkthrough-1"},{tab:"邮件",command:"插入合并域",setting:"姓名、部门、日期；逐条预览",anchor:"walkthrough-2"},{tab:"邮件",command:"完成并合并",setting:"编辑单个文档；记录：全部",anchor:"walkthrough-3"}]};return(p,e)=>{const o=r("OfficeGuide");return l(),i("div",null,[e[0]||(e[0]=t("h1",{id:"word-邮件合并、批量通知与标签",tabindex:"-1"},[d("Word 邮件合并、批量通知与标签 "),t("a",{class:"header-anchor",href:"#word-邮件合并、批量通知与标签","aria-label":'Permalink to "Word 邮件合并、批量通知与标签"'},"​")],-1)),e[1]||(e[1]=t("p",null,"邮件合并把“一份固定正文”和“多行个性化数据”组合成多份文档。名字虽然含“邮件”，也可以只生成通知、信函、信封和标签。本篇以生成培训通知文档为例，不需要发送电子邮件。",-1)),n(o,{guide:a}),e[2]||(e[2]=c('<h2 id="data" tabindex="-1">准备名单 <a class="header-anchor" href="#data" aria-label="Permalink to &quot;准备名单 {#data}&quot;">​</a></h2><p>在 Excel 新建工作表 <code>名单</code>，第一行使用唯一列名：姓名、部门、培训日期、教室、通知编号。下面输入三条虚构记录，不合并单元格，不插入小计行或说明行。</p><table tabindex="0"><thead><tr><th>姓名</th><th>部门</th><th>培训日期</th><th>教室</th><th>通知编号</th></tr></thead><tbody><tr><td>陈晨</td><td>运营</td><td>2026年11月12日</td><td>A301</td><td>001</td></tr><tr><td>李明</td><td>财务</td><td>2026年11月12日</td><td>A301</td><td>002</td></tr><tr><td>王宁</td><td>技术</td><td>2026年11月13日</td><td>B202</td><td>003</td></tr></tbody></table><p>练习中的日期用于显示，可直接保存为文字；通知编号应先把列设为文本再输入，确保前导零保留。需要 Excel 继续计算的真实日期或金额，宜保留原列，再用辅助列提供显示文字，例如 <code>=TEXT(C2,&quot;yyyy年m月d日&quot;)</code>。保存工作簿，记住路径。</p><h2 id="merge" tabindex="-1">连接名单并插入合并域 <a class="header-anchor" href="#merge" aria-label="Permalink to &quot;连接名单并插入合并域 {#merge}&quot;">​</a></h2><ol><li>打开 Word 通知模板，选择“邮件 → 开始邮件合并 → 信函”。</li><li>选择“选择收件人 → 使用现有列表”，打开刚才的工作簿，选择 <code>名单</code> 工作表并确认首行是字段名。</li><li>在称呼位置使用“插入合并域 → 姓名”，在日期和教室位置插入对应字段。</li><li>用普通文字补齐固定内容，如“请于〔培训日期〕到〔教室〕参加培训”。界面中的合并域应由按钮插入，不能仅手打尖括号模拟。</li><li>点击“预览结果”，使用上一条/下一条遍历三条记录。</li></ol><p>名单列名变化后，原来的合并域可能失效，需要重新匹配。Word 只是读取指定数据源，并不会自动理解每一列的业务含义。<a href="https://support.microsoft.com/en-us/word/use-mail-merge-for-bulk-email-letters-labels-and-envelopes?ad=us&amp;rs=en-us&amp;ui=en-us" target="_blank" rel="noopener noreferrer">微软邮件合并说明</a></p><h2 id="check" tabindex="-1">筛选、格式和异常记录 <a class="header-anchor" href="#check" aria-label="Permalink to &quot;筛选、格式和异常记录 {#check}&quot;">​</a></h2><p>在“编辑收件人列表”中筛选部门、取消选中不需要的记录，并核对剩余数量。名单中的空姓名、重复编号和错误教室应先回到源数据修正，不在每份输出中逐个补丁修改。</p><p>如果金额显示了过多小数或日期格式变化，可以在 Excel 增加明确的显示辅助列，或学习合并域的数字/日期格式开关。初学时辅助列更便于核对，但其文字结果不应反过来作为计算源。名单里含换行或特别长的部门名时，还要检查输出是否挤出一页。</p><h2 id="output" tabindex="-1">输出与标签 <a class="header-anchor" href="#output" aria-label="Permalink to &quot;输出与标签 {#output}&quot;">​</a></h2><p>选择“完成并合并 → 编辑单个文档”，先生成一份包含所选记录的合并结果，逐页核对后再打印或导出 PDF。此结果通常是一个包含多条记录的文档，不会自动为每个人创建一个独立文件；如需独立文件，应另行设计流程。</p><p>制作标签时，先在标签选项中选择打印机和标签纸规格，在首个标签设计字段与格式，再使用“更新标签”复制布局。检查“下一记录”域是否正确，先用普通纸试印并与标签纸对照位置，避免直接耗费整批标签。</p><h2 id="practice" tabindex="-1">练习与验收 <a class="header-anchor" href="#practice" aria-label="Permalink to &quot;练习与验收 {#practice}&quot;">​</a></h2><p>生成三份通知，确认陈晨和李明对应 A301，王宁对应 B202，通知编号仍有前导零。然后只筛选运营部门输出，结果应只包含一份通知。修改源表中某个人的教室，重新读取或刷新名单后再合并，确认新结果使用更新值。</p><p>电子邮件合并还涉及邮件客户端、账号、收件人和发送权限；经典 Outlook、新 Outlook 与不同平台的支持并不相同。正式批量发送前必须按实际环境单独验证，不能把成功生成文档当作成功发送邮件。</p><h2 id="walkthrough" tabindex="-1">图示跟做：批量生成三份不同姓名的通知 <a class="header-anchor" href="#walkthrough" aria-label="Permalink to &quot;图示跟做：批量生成三份不同姓名的通知 {#walkthrough}&quot;">​</a></h2><p>按上方图示切换三个关键步骤；下面保留完整操作和检查结果，便于跟做与回查。请先使用练习副本。</p><h3 id="walkthrough-1" tabindex="-1">第 1 步：连接一份能检查的名单 <a class="header-anchor" href="#walkthrough-1" aria-label="Permalink to &quot;第 1 步：连接一份能检查的名单 {#walkthrough-1}&quot;">​</a></h3><p><strong>定位：邮件 → 选择收件人。</strong></p><p>先在 Excel 建姓名、部门、日期三列和三条虚构记录，第一行只放字段名，保存并关闭。Word 进入“邮件 → 开始邮件合并 → 信函”，再选择收件人、使用现有列表，选对应工作表。核对是否识别第一行为表头，避免把列名当成第一位收件人。</p><h3 id="walkthrough-2" tabindex="-1">第 2 步：在正确位置插入字段 <a class="header-anchor" href="#walkthrough-2" aria-label="Permalink to &quot;第 2 步：在正确位置插入字段 {#walkthrough-2}&quot;">​</a></h3><p><strong>定位：邮件 → 插入合并域。</strong></p><p>先写通用通知，在称呼和部门位置插入对应合并域，不能直接输入看起来像域的尖括号文字。点击预览结果，用前后记录按钮查看三条记录，检查空姓名、长部门名和日期格式。只看第一条会遗漏后续记录造成的换行或空白。</p><h3 id="walkthrough-3" tabindex="-1">第 3 步：先生成本地文档再检查 <a class="header-anchor" href="#walkthrough-3" aria-label="Permalink to &quot;第 3 步：先生成本地文档再检查 {#walkthrough-3}&quot;">​</a></h3><p><strong>定位：邮件 → 完成并合并。</strong></p><p>选择“完成并合并 → 编辑单个文档”，合并全部记录到一个新文档。检查共有三份通知，每份姓名、部门、日期都来自对应行，再保存或导出 PDF。本练习在本地检查结果，不点击电子邮件发送；需要实际发送时还必须核对收件地址与授权。</p><h3 id="walkthrough-check" tabindex="-1">没有得到预期结果时 <a class="header-anchor" href="#walkthrough-check" aria-label="Permalink to &quot;没有得到预期结果时 {#walkthrough-check}&quot;">​</a></h3><p>前导零编号或日期显示异常时，先确认 Excel 源列的数据类型，再检查合并域格式。增加收件人后重新确认连接范围，别把旧名单预览当成完整输出。</p>',29))])}}});export{f as __pageData,k as default};
